def leakage(p):
    k = p['kappa']
    h = np.array([p['Lx'], p['Ly'], p['Lz']]) / k.shape
    out = p['sigma'].copy()
    for (axis, step) in enumerate(h):
        (a, b) = (np.moveaxis(out, axis, 0), np.moveaxis(k, axis, 0))
        for side in (0, -1):
            a[side] += 1 / (step * (1 / p['gamma_robin'] + step / (2 * b[side])))
    return out
